def verify():
    assert int("3F", 16) == 63 and format(int("0110", 2) ^ (int("0110", 2) >> 1), "04b") == "0101"
    assert bin(0b1011001).count("1") == 4
    assert 2 ** 3 == 8 and math.ceil(math.log2(5)) == 3 and math.ceil(math.log2(10)) == 4
    assert abs(1e3 / 2 ** 4 - 62.5) < 1e-9 and 4096 * 2 / 1024 == 8 and abs(0.1 * 1e-9 * 1 * 1e9 - 0.1) < 1e-12
    assert abs(1 / 8e-9 / 1e6 - 125) < 1e-9


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
